using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Diagnostics;

namespace BookService.Tests.Spec;

/// <summary>
/// Test-only SaveChangesInterceptor that classifies entity changes into
/// afterCreate/afterUpdate/afterDelete records for `emitted(...)` spec-test
/// assertions. Snapshots ChangeTracker.Entries() state in SavingChanges
/// (BEFORE the write) -- SavedChanges (after the write) resets tracked
/// entities' EntityState to Unchanged, which would lose the
/// Added/Modified/Deleted distinction this classification needs.
/// </summary>
public sealed class DotnetEventSpySaveChangesInterceptor : SaveChangesInterceptor
{
    private readonly ConcurrentBag<EmittedRecord> _recorded = new();

    public override InterceptionResult<int> SavingChanges(
        DbContextEventData eventData,
        InterceptionResult<int> result
    )
    {
        RecordPendingChanges(eventData.Context);
        return base.SavingChanges(eventData, result);
    }

    public override async ValueTask<InterceptionResult<int>> SavingChangesAsync(
        DbContextEventData eventData,
        InterceptionResult<int> result,
        CancellationToken cancellationToken = default
    )
    {
        RecordPendingChanges(eventData.Context);
        return await base.SavingChangesAsync(eventData, result, cancellationToken)
            .ConfigureAwait(false);
    }

    private void RecordPendingChanges(DbContext? context)
    {
        if (context is null)
        {
            return;
        }
        foreach (var entry in context.ChangeTracker.Entries())
        {
            var hook = ClassifyEntityState(entry.State);
            if (hook is null)
            {
                continue;
            }
            _recorded.Add(new EmittedRecord(entry.Entity.GetType().Name, hook, entry.Entity));
        }
    }

    private static string? ClassifyEntityState(EntityState state) =>
        state switch
        {
            EntityState.Added => "afterCreate",
            EntityState.Modified => "afterUpdate",
            EntityState.Deleted => "afterDelete",
            _ => null,
        };

    /// <summary>Snapshot of every record captured since the last <see cref="Reset"/>.</summary>
    public IReadOnlyCollection<EmittedRecord> RecordedEvents() => _recorded.ToArray();

    /// <summary>Clear recorded state -- called between test methods so a
    /// test never observes a sibling test's changes.</summary>
    public void Reset() => _recorded.Clear();
}

/// <summary>One classified entity-state transition (entity type name, hook
/// kind, the entity instance itself) available to `emitted(...)`
/// assertions.</summary>
public sealed record EmittedRecord(string EntityTypeName, string HookKind, object Entity);
